<script setup lang="ts">
import {historyEvidence} from '../../shared/cards/history-evidence';
import {computed,onMounted,onBeforeUnmount,ref,shallowRef} from 'vue';
import {unifiedCards,unifiedLearning,unifiedKnowledge} from '../services';
import type {Output} from '../../shared/protocol/registry';
import UiIcon from './v37/PrototypeIcon.vue';
import MarkdownContent from '../editor/MarkdownContent.vue';
import ReviewLineChart from '../components/ReviewLineChart.vue';
const props=defineProps<{deckId:string;cardId:string;initialEventId?:string;deckName?:string;backLabel?:string}>();
const emit=defineEmits<{edit:[];study:[];schedule:[];back:[];knowledge:[]}>();
const scope={deckId:props.deckId,cardId:props.cardId},content=shallowRef<Output<'card.getPublishedContent'>>(),history=ref<Output<'learning.history.list'>['items']>([]),cursor=ref<string|null>(null),mastery=shallowRef<Output<'learning.mastery.card'>>(),event=shallowRef<Output<'learning.history.get'>>(),eventContent=shallowRef<Output<'content.getVersion'>>(),knowledge=ref<string[]>([]),error=ref(''),busy=ref(false);let disposed=false;
const parts=computed(()=>{const p=content.value?.payload;if(!p)return[];if(p.encoding==='question-v1')return[{label:'题干',text:p.fields.material+'\n\n'+p.fields.stem},...p.fields.options.map((o,i)=>({label:'选项 '+(i+1),text:o.markdown})),{label:'答案',text:p.fields.options.find(o=>o.optionId===p.fields.correctOptionId)?.markdown??'未设置'},{label:'解析',text:p.fields.analysis}];if(p.encoding==='qa-v1')return[{label:'问题',text:p.fields.front},{label:'答案',text:p.fields.back},{label:'补充',text:p.fields.supplement}];if(p.encoding==='direct-v1')return[{label:'正文',text:p.fields.body}];return[{label:'题干',text:p.fields.stem},{label:'选项',text:p.fields.options},{label:'答案',text:p.fields.answer},{label:'解析',text:p.fields.analysis}];});
const modeName=computed(()=>content.value?{question:'错题复盘',qa:'问答记忆',direct:'直接记忆'}[content.value.mode]:'');
const records=computed(()=>[...history.value].reverse().map((r,i)=>({id:r.eventId,ordinal:i+1,createdAt:r.createdAt,selfScore:r.scoreTenths===null?null:r.scoreTenths/10,elapsedSeconds:r.elapsedSeconds,correct:r.objectiveCorrect,effective:true})));
const evidence=computed(()=>historyEvidence(event.value,eventContent.value));
async function more(){busy.value=true;try{const p=await unifiedLearning.history({...scope,after:cursor.value});if(!disposed){history.value.push(...p.items);cursor.value=p.nextCursor;}}catch(e){error.value=String(e);}finally{busy.value=false;}}
async function select(id:string){busy.value=true;try{const result=await unifiedLearning.event({...scope,eventId:id});const version=await unifiedCards.getVersion({...scope,versionId:result.contentVersionId});if(!disposed){event.value=result;eventContent.value=version;}}catch(e){error.value=String(e);}finally{busy.value=false;}}
async function load(){busy.value=true;error.value='';content.value=undefined;history.value=[];event.value=undefined;eventContent.value=undefined;try{const [c,h,m,links,tree]=await Promise.all([unifiedCards.getPublishedContent(scope),unifiedLearning.history(scope),unifiedLearning.mastery(scope),unifiedKnowledge.links(scope),unifiedKnowledge.tree({deckId:props.deckId})]);if(!disposed){content.value=c;history.value=h.items;cursor.value=h.nextCursor;mastery.value=m;knowledge.value=links.nodeIds.map(id=>tree.nodes.find(n=>n.nodeId===id)?.name??'已失效知识点');if(props.initialEventId)await select(props.initialEventId);}}catch(e){error.value=String(e);}finally{busy.value=false;}}
onMounted(load);onBeforeUnmount(()=>{disposed=true;});
defineExpose({selectedEvent:()=>event.value?.eventId??''});
</script>
<template>
 <article aria-label="卡片详情" class="card-detail-page r3-detail" :aria-busy="busy"><p v-if="error" role="alert">{{error}} <button class="button" @click="load">重新读取详情</button><button class="button" @click="emit('back')">{{backLabel??'返回列表'}}</button></p><template v-if="content">
  <div class="page-heading"><div><h1>卡片详情</h1><p>{{deckName??'当前卡片集'}} / {{modeName}} · 全部内容和历史分开按需加载。</p></div><div class="heading-actions"><button class="button" @click="emit('back')"><UiIcon name="back"/>{{backLabel??'返回列表'}}</button><button class="button primary" @click="emit('edit')"><UiIcon name="cards" :size="15"/>编辑卡片</button></div></div>
  <section class="surface padded card-detail-head"><div class="section-heading"><div><h2>{{content.title||'未命名卡片'}}</h2><p class="small-muted">{{content.payload?.fields.source||'未填写来源'}} · {{knowledge.join(' / ')||'尚未关联知识点'}}</p></div><span class="mode-label"><span class="dot"/>{{modeName}}</span></div>
   <div class="detail-metrics"><div><span>累计复盘</span><strong>{{mastery?.historyCount??'—'}} 次</strong></div><div><span>最近自评</span><strong>{{history[0]?.scoreTenths==null?'未记录':(history[0].scoreTenths/10).toFixed(1)+' / 10'}}</strong></div><div><span>当前学习周期</span><strong>{{mastery?.status==='pending'?'待评估':mastery?.status==='unseen'?'未复盘':(mastery?.observations??0)+' 次观察'}}</strong></div><div><span>历史记录</span><strong>完整保留</strong></div></div>
  </section>
  <div class="analytics-layout margin-top"><section class="surface padded"><div class="section-heading"><h2>单卡学习趋势</h2><span class="tiny-meta">已加载记录 · 自评分 / 用时</span></div><ReviewLineChart :records="records" metric="selfScore" title="已加载记录 · 自评分" :selected-id="event?.eventId??''" unified neutral @select="select"/>
   <details><summary>查看用时趋势</summary><ReviewLineChart :records="records" metric="elapsedSeconds" title="已加载记录 · 用时" :selected-id="event?.eventId??''" unified neutral @select="select"/></details>
  </section><section class="surface padded"><div class="section-heading"><h2>最近三次学习</h2><button class="text-button" @click="($refs.historyPanel as HTMLDetailsElement).open=true">全部历史 →</button></div><div v-for="r in history.slice(0,3)" :key="r.eventId" class="history-row"><span class="score-token">{{r.scoreTenths==null?'—':(r.scoreTenths/10).toFixed(1)}}</span><div class="history-row-main"><strong>{{new Date(r.createdAt).toLocaleDateString('zh-CN')}}</strong><small>{{r.elapsedSeconds??'未记录'}} 秒 · {{r.objectiveCorrect===null?'主观自评':r.objectiveCorrect?'回答正确':'回答错误'}}</small></div><button class="text-button" :disabled="busy" @click="select(r.eventId)">查看</button></div><div v-if="!history.length" class="empty-state">还没有学习记录</div></section></div>
  <section class="surface padded margin-top"><div class="section-heading"><h2>当前内容与关联知识点</h2><button class="text-button" @click="emit('edit')">编辑内容 →</button></div><section v-for="(p,i) in parts" :key="i" class="card-content-part"><h3>{{p.label}}</h3><MarkdownContent :markdown="p.text" :media-refs="content.mediaRefs"/></section><div class="compact-actions margin-top"><button class="button small" @click="emit('study')"><UiIcon name="play" :size="15"/>复盘此卡片</button><button class="button small" @click="emit('knowledge')"><UiIcon name="brain"/>关联知识点</button><button class="button small" @click="($refs.historyPanel as HTMLDetailsElement).open=true"><UiIcon name="clock"/>查看学习历史</button><button class="button small" @click="emit('schedule')">单卡调度</button></div></section>
  <details ref="historyPanel" class="surface padded margin-top" :open="!!event"><summary>复盘趋势与历史</summary><div class="detail-history-list"><button v-for="r in history" :key="r.eventId" :disabled="busy" @click="select(r.eventId)">{{new Date(r.createdAt).toLocaleString('zh-CN')}} · {{r.scoreTenths===null?'未记录':(r.scoreTenths/10).toFixed(1)}} 分 · {{r.elapsedSeconds??'未记录'}} 秒</button></div><button v-if="cursor" :disabled="busy" @click="more">更多历史记录</button>
   <section v-if="event" aria-label="当次复盘证据"><h3>{{new Date(event.createdAt).toLocaleString('zh-CN')}}</h3><p>自评 {{event.scoreTenths===null?'未记录':(event.scoreTenths/10).toFixed(1)}} · 客观{{event.objectiveCorrect===null?'不适用':event.objectiveCorrect?'正确':'错误'}} · 评级 {{event.rating??'未记录'}}</p><p>当时选择：{{evidence.choice}}</p><p>原始思路：{{evidence.thought||'未记录'}}</p><p>错因：{{evidence.faults.join('；')||'未记录'}}</p><p>知识漏洞：{{evidence.gaps||'未记录'}}</p><p>反思：{{evidence.reflection||'未记录'}}</p><p>当时知识点：{{event.native?.knowledge.map(k=>k.path.join(' › ')).join('、')|| (event.knowledgeSnapshot?'旧记录保留了知识快照，未提供统一父级路径':'无') }}</p><details v-if="event.knowledgeSnapshot&&!event.native"><summary>当时的原始知识快照</summary><pre>{{event.knowledgeSnapshot}}</pre></details></section>
  </details></template><p v-else-if="!error">正在读取当前内容…</p>
 </article>
</template>
